-- Dansk portion 5 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6588-9983.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish5'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish5', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6588,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Økonomer taler om 'højkonjunktur'. Hvad kendetegner en sådan periode?","o":["mange er arbejdsløse, og forbruget falder","staten holder op med at opkræve skat","mange har arbejde, og forbruget stiger","butikkerne holder lukket i længere tid"],"a":"mange har arbejde, og forbruget stiger","r":"Konjunkturer beskriver, hvordan det går med økonomien. Ved højkonjunktur er der gang i produktion, salg og beskæftigelse."},
{"l":6611,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvem er en 'nævning' i en retssag?","o":["den advokat, der forsvarer den tiltalte person","den person, der har anmeldt sagen","den betjent, der sørger for sikkerheden","en almindelig borger, der er med til at dømme"],"a":"en almindelig borger, der er med til at dømme","r":"Nævninger er lægfolk, som bliver udpeget til at dømme sammen med juridiske dommere i alvorlige straffesager."},
{"l":6631,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket bindeord passer: 'Det regnede, ___ vi tog alligevel til stranden.'?","o":["men","fordi","hvis","selvom"],"a":"men","r":"Regnen var et problem, men vi tog af sted alligevel. Det er en modsætning, og den viser 'men'; med de andre ord giver sætningen ikke mening."},
{"l":6653,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om skraldespanden står i passiv?","o":["Vi skal tømme skraldespanden i aften.","Skraldespanden skal tømmes i aften.","Far vil tømme skraldespanden i aften.","Du kan tømme skraldespanden i aften."],"a":"Skraldespanden skal tømmes i aften.","r":"Efter hjælpeverbet 'skal' står 'tømmes' i s-form, så sætningen er passiv. Skraldespanden er grundled, men gør ikke selv noget."},
{"l":6673,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Efter 6-0-nederlaget konstaterede træneren, at holdet nok ikke havde haft sin bedste dag.' Hvilket sprogligt virkemiddel bruger træneren?","o":["Overdrivelse","Gentagelse","Underdrivelse","Personificering"],"a":"Underdrivelse","r":"6-0 er et voldsomt nederlag, og træneren siger meget mindre, end situationen giver grund til. Det er en underdrivelse."},
{"l":6695,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Lægen målte hans ___ og sagde, at han havde feber.'","o":["tempratur","temperatuur","temparatur","temperatur"],"a":"temperatur","r":"Mange sluger e'et i midten, når de taler, men det skal med: tem-pe-ra-tur."},
{"l":6708,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning bruger lang tillægsform rigtigt foran 'eventyr'?","o":["Vi læste et spændende eventyr.","Vi læste et spændendet eventyr.","Vi læste en spændende eventyr.","Vi læste et spændendes eventyr."],"a":"Vi læste et spændende eventyr.","r":"Lang tillægsform på -ende bøjes ikke og får ikke -t. 'Eventyr' er et intetkønsord og skal have 'et' foran."},
{"l":6731,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Ordet 'uretfærdig' er dannet af 'retfærdig' med forstavelsen u-. Hvad sker der?","o":["ordklassen skifter fra tillægsord til navneord","betydningen vendes, men ordklassen er den samme","ordklassen skifter fra tillægsord til udsagnsord","hverken betydning eller ordklasse ændrer sig"],"a":"betydningen vendes, men ordklassen er den samme","r":"Forstavelsen u- giver ordet modsat betydning, men begge ord er tillægsord. Endelser kan derimod ofte skifte ordklasse."},
{"l":6753,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hvem vil ikke gerne have en renere skolegård?' Hvad kaldes denne type sætning i en tale?","o":["sammenligning","allitteration","retorisk spørgsmål","personifikation"],"a":"retorisk spørgsmål","r":"Afsenderen venter ikke et svar, for svaret er givet på forhånd. Spørgsmålet skal få modtageren til at give ham ret."},
{"l":6773,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Byen fik en ___ kroner til en ny svømmehal.'","o":["milion","millijon","miljon","million"],"a":"million","r":"Ordet har dobbelt-l og slutter på -ion."},
{"l":6794,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Tabellen viser, hvor ofte eleverne på Skovbyskolen spiser morgenmad: hver dag 60 procent, nogle dage 30 procent, aldrig 10 procent. Skolebladet skriver: Næsten halvdelen af eleverne får ingen morgenmad!' Hvorfor er bladets sætning misvisende?","o":["Den regner dem med, der kun springer over indimellem","Den lægger procenterne sammen, så de ikke giver 100","Den tager ikke højde for, hvad eleverne spiser","Den viser ikke, hvor stor skolen er i alt"],"a":"Den regner dem med, der kun springer over indimellem","r":"Bladet lægger 30 og 10 sammen og får næsten halvdelen. Men de 30 procent spiser jo morgenmad nogle dage."},
{"l":6804,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken sætning indeholder en sammenligning?","o":["Stilheden var et tæppe over byen.","Stilheden var tung som bly.","Der var stille på biblioteket i dag.","Stilheden bed sig fast i rummet."],"a":"Stilheden var tung som bly.","r":"Ordet 'som' sammenligner stilheden med bly. De andre billeder mangler 'som', eller også er de slet ikke billeder."},
{"l":6825,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord passer? 'Teatret har en ___, hvor man kan hænge sin frakke.'","o":["gaderobe","garderobbe","garderobe","gardarobe"],"a":"garderobe","r":"Ordet kommer fra fransk. Husk r'et efter ga-, og at der er ét b."},
{"l":6849,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Elever siger, at mobilen er nødvendig for at holde kontakt med forældrene. Men skolen har en telefon på kontoret, og for 30 år siden kunne man fint finde sine børn uden.' Hvilken slags argument bruger skribenten til sidst?","o":["Forskere har vist, at mobiler er skadelige","Kontorets telefon er billigere end en mobil","Forældrene ønsker selv at forbyde mobilen","Det gik fint før, så det går også fint nu"],"a":"Det gik fint før, så det går også fint nu","r":"Skribenten henviser til fortiden som bevis. Der nævnes hverken forskning, pris eller forældrenes ønsker."},
{"l":6868,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Han pådrog sig en slem forkølelse på lejrturen.' Hvad skete der?","o":["han blev forkølet","han undgik forkølelsen","han kom sig over forkølelsen","han smittede de andre"],"a":"han blev forkølet","r":"'Pådrage sig' bruges om noget ubehageligt, man får, for eksempel en sygdom, en skade eller en bøde."},
{"l":6890,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? Det er stedet, hvor skuespillere optræder for et publikum.","o":["theater","teater","teatter","tiater"],"a":"teater","r":"På dansk skrives ordet uden h, selvom det kommer fra græsk."},
{"l":6904,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det latinske navn for et verbums tillægsform?","o":["infinitiv","imperativ","participium","præsens"],"a":"participium","r":"Tillægsform hedder participium. Infinitiv er navneform, imperativ er bydeform, og præsens er nutid."},
{"l":6926,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Alle elever i 7.a bor i Lindby. Nogle elever i 7.a spiller skak.' Hvilket udsagn må være rigtigt, hvis begge sætninger passer?","o":["Alle skakspillere i Lindby går i 7.a","Alle i Lindby spiller skak","Ingen fra de andre klasser spiller skak","Nogle af dem, der bor i Lindby, spiller skak"],"a":"Nogle af dem, der bor i Lindby, spiller skak","r":"Skakspillerne fra 7.a bor jo alle i Lindby. Om andre i byen eller på skolen spiller, siger teksten ikke noget om."},
{"l":6948,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Den ___ dreng fik et plaster på knæet.'?","o":["sårede","såret","såre","sårer"],"a":"sårede","r":"Efter 'den' står tillægsord i bestemt form. Kort tillægsform bøjes på samme måde: 'en såret dreng', men 'den sårede dreng'."},
{"l":6968,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Jeg blev meget ___, da alle råbte tillykke.'","o":["overasket","overrasket","overrasked","overraskt"],"a":"overrasket","r":"Ordet er sammensat med 'over-', og derefter følger -rasket. Derfor er der dobbelt-r."},
{"l":6992,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"En reklame for løbesko viser en kendt, succesfuld løber, der anbefaler skoene. Hvilken appelform udnytter reklamen især?","o":["logos","påstand","etos","ironi"],"a":"etos","r":"Reklamen låner troværdighed fra løberen. Når afsenderens anseelse skal overbevise os, er det etos."},
{"l":7003,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Rektor beskrives som 'rationel'. Hvad kendetegner hende?","o":["hun træffer sine valg ud fra følelser","hun træffer sine valg efter lodtrækning","hun undgår at træffe valg overhovedet","hun træffer sine valg ud fra fornuft"],"a":"hun træffer sine valg ud fra fornuft","r":"Den rationelle tænker logisk og vejer fordele mod ulemper, før en beslutning bliver taget. 'Ratio' betyder fornuft på latin."},
{"l":7025,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ledsætning har rigtig ordstilling: 'Jeg ved ikke, …'?","o":["hvor hun bor","hvor bor hun","hun hvor bor","bor hvor hun"],"a":"hvor hun bor","r":"I en spørgende ledsætning kommer grundleddet før verbet. 'Hvor bor hun?' er ordstillingen i et direkte spørgsmål."},
{"l":7047,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Sætningen begynder med 'Heldigvis'. Hvilken ordstilling er rigtig?","o":["Heldigvis Ali fandt sin taske.","Heldigvis fandt Ali sin taske.","Heldigvis sin taske Ali fandt.","Heldigvis fandt sin taske Ali."],"a":"Heldigvis fandt Ali sin taske.","r":"Biordet står på første plads, så verbet følger straks efter og derefter grundleddet. Først bagefter kommer genstandsleddet."},
{"l":7069,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi flyttede ind i huset i maj. Alle værelser var hvide og duftede af maling. I august fik køkkenbordet sin første ridse af lillebrors cykelhjelm. Først da begyndte jeg at sove godt.' Hvad udtrykker den sidste sætning?","o":["At lugten af maling endelig var forsvundet fra huset","At fortælleren var træt efter alt arbejdet med at flytte ind","At huset først føltes som deres hjem efter ridsen","At sommeren var ovre, og nætterne var blevet mørkere"],"a":"At huset først føltes som deres hjem efter ridsen","r":"Ridsen er det første spor af, at familien bor i det rene hus, og først da sover fortælleren godt. Teksten siger 'først da' lige efter ridsen, ikke efter lugten af maling."},
{"l":7088,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kendetegner ironi som sprogligt virkemiddel?","o":["At sige det samme flere gange i træk","At beskrive en ting med mange detaljer","At bruge mange ord, der begynder ens","At sige det modsatte af det, man mener"],"a":"At sige det modsatte af det, man mener","r":"Ved ironi siger man noget, men mener noget andet, og modtageren skal kunne gennemskue det."},
{"l":7111,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Der er ___ mælk eller brød i køleskabet.'","o":["hverken","verken","hvirken","hverkan"],"a":"hverken","r":"Ordet skrives med stumt h foran v, ligesom 'hver', og det står sammen med 'eller'."},
{"l":7135,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Når forskere kalder noget en teori, betyder det ikke, at det er et gæt. Det er en forklaring, der er blevet undersøgt grundigt. I hverdagen bruger vi tit ordet anderledes.' Hvad vil teksten især rette op på?","o":["At mange tror, at forskere aldrig undersøger deres gæt","At mange tror, at en teori bare er et gæt","At mange tror, at et gæt er bedre end grundig forskning","At forskere taler for lidt om deres teorier"],"a":"At mange tror, at en teori bare er et gæt","r":"Hos forskere betyder 'teori' en forklaring, der er undersøgt grundigt. I hverdagen bruger vi tit ordet om et gæt, og det er den forveksling, teksten vil rydde op i."},
{"l":7157,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det egentlige grundled i: 'Det er sjovt at spille skak.'?","o":["Det","sjovt","at spille skak","skak"],"a":"at spille skak","r":"Spørg: Hvad er sjovt? Svaret er 'at spille skak'. 'Det' er et formelt grundled, der peger frem mod det egentlige."},
{"l":7175,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En kontrollant 'konstaterer', at døren er låst. Hvad gør hun?","o":["spørger, om det virkelig er sandt","håber, at det forholder sig sådan","gætter på, at det nok passer","slår fast, at det er sådan"],"a":"slår fast, at det er sådan","r":"Hun har selv tjekket døren, så hun gætter ikke. Hun siger bare, hvordan det er."},
{"l":7197,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Mikkel skal vælge mellem at holde et løfte og at tage med til en fest, og begge valg koster noget. Hvad kaldes sådan en situation?","o":["et dilemma","et paradoks","et citat","et postulat"],"a":"et dilemma","r":"I et dilemma står man mellem to muligheder, som begge har en pris. Ordet kommer af græsk og rummer 'di', som betyder 'to'."},
{"l":7216,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad er fejlen i sætningen 'Alle elever i 8. klasse, skal møde kl. 9.'?","o":["Der mangler et komma efter ordet 'skal'","Der står komma mellem grundled og udsagnsled","Ordenstallet må ikke have punktum","Klokkeslættet skal skrives helt ud"],"a":"Der står komma mellem grundled og udsagnsled","r":"'Alle elever i 8. klasse' er grundleddet, og det må ikke skilles fra udsagnsleddet med komma."},
{"l":7237,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det betyder ikke noget, om jeg slukker lyset. Jeg er jo kun én. Sådan tænker millioner af mennesker hver aften.' Hvad er tekstens pointe?","o":["Man kan ikke spare noget på at slukke lyset","Millioner af mennesker går for sent i seng","Mange små valg får tilsammen betydning","Elregningen er for høj for den enkelte"],"a":"Mange små valg får tilsammen betydning","r":"Den sidste sætning undergraver de to første: Hvis millioner tænker sådan, er det ikke længere kun én. Det er den skjulte pointe."},
{"l":7257,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'tage bladet fra munden'?","o":["at holde op med at tale","at rose en anden højlydt","at tale meget langsomt","at sige sin mening lige ud"],"a":"at sige sin mening lige ud","r":"Den, der tager bladet fra munden, holder ikke længere noget tilbage. Billedet er, at intet længere dækker for det, man vil sige."},
{"l":7280,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder nogenlunde det samme som 'temporær'?","o":["midlertidig","årlig","tilfældig","tidlig"],"a":"midlertidig","r":"Temporær kommer af latin 'tempus', som betyder tid. Noget temporært varer kun et stykke tid, modsat noget permanent."},
{"l":7300,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En kommune betalte en dusør for hver rotte, der blev fanget. Snart begyndte nogle borgere at opdrætte rotter for at få dusøren.' Hvad viser eksemplet?","o":["Rotter formerer sig hurtigere end de fleste andre dyr i en by","En belønning kan gøre problemet værre","Borgerne var ikke interesserede i at fange rotter","Kommunen burde have sat dusøren meget højere"],"a":"En belønning kan gøre problemet værre","r":"Folk opdrættede rotter for at få pengene, og så blev der flere rotter og ikke færre."},
{"l":7317,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Antallet af stjålne cykler ved Vestskolen er steget med 50 procent, skriver avisen. I sidste uge blev tre cykler meldt stjålet mod to ugen før.' Hvorfor kan procenttallet virke misvisende?","o":["Tre cykler er et meget stort antal","Avisen har regnet procenten forkert","Små tal giver hurtigt store procenter","Stigningen er større end 50 procent"],"a":"Små tal giver hurtigt store procenter","r":"Fra to til tre er rigtigt nok 50 procent, men i virkeligheden drejer det sig om én cykel. Procenter kan puste små ændringer op."},
{"l":7340,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord ligger tættest på 'fordomsfri'?","o":["forudseende","frygtløs","forsigtig","åbensindet"],"a":"åbensindet","r":"En fordom er en mening, man har dannet sig på forhånd. Den, der er fordomsfri, møder altså andre med et åbent sind."},
{"l":7356,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hvorfor sagde jeg det? Dumt, dumt. Nu kigger hun. Smil. Nej, ikke så meget. Bare gå.' Hvilken fremstillingsform er det?","o":["indre monolog","dialog","referat","miljøbeskrivelse"],"a":"indre monolog","r":"Vi følger personens tanker, præcis som de opstår, i korte brudstykker. Det er en indre monolog. Ingen siger noget højt."},
{"l":7379,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves ordet? 'En ___ i butikken hjalp mig med at finde skoene.'","o":["ekspedent","ekspedient","eksspedient","ekspediant"],"a":"ekspedient","r":"Ordet har ks og ender på -ient. Mange glemmer i'et, men det skal med."},
{"l":7399,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Det ___ os at nå toget i går.'?","o":["lykkes","lykkede","lykkedes","lykket"],"a":"lykkedes","r":"'I går' kræver datid. Datid af 'lykkes' hedder 'lykkedes', og verbet beholder altid sit -s."},
{"l":7414,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning sætter anførselstegn rigtigt om eventyrets titel?","o":["Vi læste »Den grimme« ælling i klassen.","Vi »læste Den grimme ælling« i klassen.","Vi læste Den »grimme ælling« i klassen.","Vi læste »Den grimme ælling« i klassen."],"a":"Vi læste »Den grimme ælling« i klassen.","r":"Anførselstegnene skal stå om hele titlen og ikke om mere eller mindre."},
{"l":7435,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Lægen talte både om fysisk og ___ sundhed.'","o":["psykisk","sykisk","psychisk","psykkisk"],"a":"psykisk","r":"Ordet begynder med ps, selvom p'et ikke høres. Det kommer fra græsk 'psyke', der betyder sjæl."},
{"l":7454,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvor længe skal vi finde os i, at vores skolemad er dårligere end nabokommunens?' Hvad tager spørgsmålet for givet?","o":["At nabokommunen bruger for mange penge på maden","At skolemaden allerede er dårligere end hos naboen","At eleverne selv bør lave deres skolemad","At man endnu ikke ved, hvem der har den bedste mad"],"a":"At skolemaden allerede er dårligere end hos naboen","r":"Der spørges kun 'hvor længe', ikke om maden virkelig er dårligere. Det bliver bare sagt, som om alle ved det."},
{"l":7476,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket verbum binder grundleddet sammen med omsagnsleddet, ligesom 'være' og 'blive': 'Mads ___ rolig under hele prøven.'?","o":["skrev","arbejdede","forblev","tænkte"],"a":"forblev","r":"'Forblive' betyder 'blive ved med at være': Mads var rolig hele tiden. 'Skrev', 'arbejdede' og 'tænkte' fortæller, hvad Mads gjorde, og binder ikke på den måde."},
{"l":7498,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren streger en sætning ud, fordi den er 'redundant'. Hvad er der galt med den?","o":["den er stavet forkert flere steder","den er for svær at forstå for læseren","den er uhøflig over for modtageren","den gentager noget, der allerede er sagt"],"a":"den gentager noget, der allerede er sagt","r":"Redundant betyder overflødig, fordi oplysningen allerede findes. I en god, kort tekst fjerner man den slags gentagelser."},
{"l":7511,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I en undersøgelse fik den ene gruppe rigtig medicin, mens den anden fik sukkerpiller. Ingen vidste, hvad de fik. Begge grupper fik det bedre, den første gruppe dog en smule mere.' Hvad tyder resultatet på?","o":["Troen på en pille kan også have en virkning","Sukkerpiller virker bedre end rigtig medicin","Den rigtige medicin har slet ingen virkning","Forsøgspersonerne vidste, hvad de havde fået"],"a":"Troen på en pille kan også have en virkning","r":"Sukkerpiller har ingen medicin i sig, og alligevel fik folk det bedre, fordi de troede på pillen. Medicinen virker også, for den gruppe fik det lidt bedre end den anden."},
{"l":7531,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket bindeord viser, at hun gjorde det på trods: 'Hun gik ud, ___ det stormede.'?","o":["fordi","skønt","eftersom","hvis"],"a":"skønt","r":"'Skønt' betyder det samme som 'selvom' og angiver en indrømmelse. 'Fordi' og 'eftersom' angiver årsag."},
{"l":7551,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kaldes det i argumentation, som man vil overbevise andre om?","o":["belæg","hjemmel","påstand","styrkemarkør"],"a":"påstand","r":"Påstanden er det synspunkt, man vil have andre til at acceptere. Belægget er det, man støtter påstanden med."},
{"l":7573,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'forfægte' en holdning?","o":["at skjule den for andre","at opgive den igen","at lytte til den i stilhed","at forsvare den ivrigt"],"a":"at forsvare den ivrigt","r":"'Forfægte' er beslægtet med 'fægte'. Billedet er, at man kæmper for sit synspunkt, som man kæmper med en klinge."},
{"l":7596,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør man, når man 'tager forbehold' i en aftale?","o":["man siger, at noget kan ændre den","man bekræfter, at den gælder fuldt ud","man sletter den og laver en ny","man skriver den ned for at huske den"],"a":"man siger, at noget kan ændre den","r":"Et forbehold er en begrænsning: Man siger ja, men med et 'hvis'. Man holder altså en mulighed åben for, at noget kan ændre sig."},
{"l":7614,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Skoven stod som et tempel. I træernes sus hørte jeg det evige, og min sjæl blev ét med alt.' Hvilken periode minder teksten mest om?","o":["det moderne gennembrud","romantikken","modernismen","oplysningstiden"],"a":"romantikken","r":"Følelsen af at smelte sammen med en hellig natur er typisk romantisk. Naturen bliver et sted, hvor det guddommelige viser sig."},
{"l":7634,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket tegn kan erstatte semikolonet, uden at det bliver forkert, i: 'Bussen kom ikke; vi gik.'?","o":["apostrof","bindestreg","punktum","anførselstegn"],"a":"punktum","r":"Semikolon står mellem to hele hovedsætninger, og de kunne lige så godt stå som to selvstændige sætninger."},
{"l":7656,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvor mange kommaer skal der mindst stå i 'Da vi havde set filmen som Emil anbefalede gik vi hjem.'?","o":["to kommaer","tre kommaer","intet komma","ét komma"],"a":"ét komma","r":"Kun slutkommaet efter 'anbefalede' er et krav. Et komma foran 'som' er et startkomma og derfor valgfrit."},
{"l":7678,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det gammeldags ord 'thi' i sætningen 'Han blev hjemme, thi han var syg'?","o":["for","men","hvis","selvom"],"a":"for","r":"'Thi' er et gammelt bindeord, som angiver en årsag. I dag ville man sige 'for' eller 'fordi'."},
{"l":7700,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning skriver forkortelsen af 'eventuelt' rigtigt?","o":["Ring e.v.t. i morgen.","Ring evt. i morgen.","Ring even. i morgen.","Ring ev.t i morgen."],"a":"Ring evt. i morgen.","r":"'Eventuelt' er ét ord, så forkortelsen har kun ét punktum til sidst."},
{"l":7717,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan er en person, der er 'pedantisk'?","o":["meget optaget af at hjælpe andre mennesker","sjusket og ligeglad med, om tingene passer","overdrevent optaget af små regler og detaljer","hurtig til at grine og finde på noget sjovt"],"a":"overdrevent optaget af små regler og detaljer","r":"Den pedantiske person hænger sig i småting og kan ikke lade en lille fejl passere. Ordet har en negativ klang."},
{"l":7739,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad udtrykker en 'nedladende' tone?","o":["at man er træt og vil hjem","at man er bange for den anden","at man er ked af det skete","at man ser ned på den anden"],"a":"at man ser ned på den anden","r":"Den, der er nedladende, behandler andre, som om de står under en selv. Man kan være høflig i ordene og alligevel nedladende i tonen."},
{"l":7760,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Biblioteket bør holde åbent om søndagen, for mange har først tid i weekenden.' Hvilken antagelse ligger bag argumentet?","o":["Et bibliotek bør have åbent, når folk har tid","Søndag er ugens bedste dag at læse på","Mange mennesker arbejder i weekenden","Bøger er billigere om søndagen end ellers"],"a":"Et bibliotek bør have åbent, når folk har tid","r":"Den underforståede antagelse er hjemlen. Den forklarer, hvorfor folks fritid er en god grund til at ændre åbningstiden."},
{"l":7777,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'sekundærkilde' i en historieopgave?","o":["en kilde, der stammer direkte fra begivenheden","en kilde, der gengiver oplysninger fra andre kilder","en kilde, der kun er lavet til brug i skolen","en kilde, der er blevet ødelagt med tiden"],"a":"en kilde, der gengiver oplysninger fra andre kilder","r":"Sekundær betyder 'den anden i rækken'. En sekundærkilde bygger på andres oplysninger, mens en primærkilde stammer direkte fra begivenheden."},
{"l":7799,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad tror en 'fatalist' om livet?","o":["at det, der sker, kun skyldes ens egen vilje","at det, der sker, altid ender lykkeligt","at det, der sker, er bestemt på forhånd","at det, der sker, kan beregnes af forskere"],"a":"at det, der sker, er bestemt på forhånd","r":"Fatalisme kommer af latin 'fatum', som betyder skæbne. Fatalisten mener, at man ikke kan ændre sin skæbne."},
{"l":7814,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun tager altid trappen, fordi hun har 'klaustrofobi'. Hvad er hun bange for?","o":["store højder","mørke kældre","mange mennesker","lukkede rum"],"a":"lukkede rum","r":"'Klaustro' kommer af latin 'claustrum', som betyder lukket sted, og 'fobi' betyder frygt. Derfor undgår hun elevatoren."},
{"l":7832,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilke ord skal have stort: 'Min storebror studerer på københavns universitet og bor på Østerbro.'?","o":["københavns og universitet","kun ordet københavns","kun ordet universitet","kun ordet storebror"],"a":"københavns og universitet","r":"Københavns Universitet er et navn på en institution, og begge ord i navnet får stort."},
{"l":7854,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket tegn kan indlede en replik i en roman i stedet for anførselstegn?","o":["apostrof","tankestreg","semikolon","bindestreg"],"a":"tankestreg","r":"I skønlitteratur kan en replik begynde med tankestreg, for eksempel: – Kommer du?"},
{"l":7876,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når Asta sammenlignes med sin storebror?","o":["Asta er lige så høj, som sin storebror.","Asta er, lige så høj som sin storebror.","Asta er lige så høj som sin storebror.","Asta er lige, så høj som sin storebror."],"a":"Asta er lige så høj som sin storebror.","r":"'som sin storebror' har intet udsagnsled og er altså ikke en ledsætning, så der skal ikke komma."},
{"l":7898,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning skriver forkortelsen af 'procent' rigtigt?","o":["Cirka 20 p.c.t. af eleverne cykler.","Cirka 20 pc.t af eleverne cykler.","Cirka 20 p,ct af eleverne cykler.","Cirka 20 pct. af eleverne cykler."],"a":"Cirka 20 pct. af eleverne cykler.","r":"'Procent' er ét ord og forkortes pct. med ét punktum til sidst."},
{"l":7919,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kendetegnede en 'fæstebonde'?","o":["han lejede sin gård af en godsejer","han ejede selv en stor gård","han solgte korn til fremmede lande","han arbejdede som kusk på godset"],"a":"han lejede sin gård af en godsejer","r":"En fæstebonde boede på en gård, der tilhørte godsejeren. Til gengæld betalte han afgifter og udførte hoveri."},
{"l":7939,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Det kan ___ mig, når nogen smasker ved bordet.'","o":["iritere","irritere","irrittere","irretere"],"a":"irritere","r":"Ordet har dobbelt-r og ét t, og det står i navneform efter 'kan'."},
{"l":7960,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kalder man et helt nyt ord i sproget?","o":["eufemisme","synonym","neologisme","homonym"],"a":"neologisme","r":"En neologisme er et nyord. Et synonym er et ord med næsten samme betydning som et andet."},
{"l":7981,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Kommunen sendte en ___ meddelelse til borgerne.'","o":["offisiel","officiell","oficiel","officiel"],"a":"officiel","r":"Ordet har dobbelt-f, og s-lyden skrives med c. Det slutter med ét l."},
{"l":8000,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Den, der aldrig har fejlet i et laboratorium, har måske bare aldrig prøvet noget nyt. Et forsøg, der mislykkes, er ikke spildt. Det lukker en vej, så de næste forskere kan gå en anden.' Hvilken antagelse bygger teksten på uden at sige det?","o":["At de næste faktisk får besked om det mislykkede forsøg","At et mislykket forsøg er mere værd end et vellykket","At nye idéer altid fører til et resultat til sidst","At dygtige forskere sjældent fejler i laboratoriet"],"a":"At de næste faktisk får besked om det mislykkede forsøg","r":"En vej er kun lukket for de næste, hvis de kender til fejlen. Teksten siger, at et mislykket forsøg ikke er spildt, men ikke at det er bedre end et vellykket."},
{"l":8018,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør man, når man 'relativerer' et problem?","o":["man fortæller det videre til sin familie","man sætter det i forhold til noget andet","man finder den rette løsning på det","man afviser, at det overhovedet findes"],"a":"man sætter det i forhold til noget andet","r":"At relativere er at vise, at noget kun gælder i forhold til noget andet. Dermed virker det ofte mindre absolut, end det så ud til."},
{"l":8037,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad udtrykker datidsformen 'var' i: 'Hvis jeg var dig, ville jeg tage jakke på.'?","o":["noget, der faktisk skete i går","en bydeform til den, man taler med","noget tænkt, der ikke er virkeligt","noget, der med sikkerhed vil ske"],"a":"noget tænkt, der ikke er virkeligt","r":"Her handler datid ikke om fortiden. Den viser, at det kun er tænkt, for jeg er jo ikke dig."},
{"l":8059,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led bliver fremhævet i: 'Det var Sara, der fandt nøglen.'?","o":["nøglen","fandt","Det","Sara"],"a":"Sara","r":"Med 'det var …, der' trækker man et led frem. Sætningen understreger, at det netop var Sara og ikke en anden."},
{"l":8079,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'I faget ___ stiller man store spørgsmål om livet.'","o":["filosofi","filosophi","fillosofi","filosovi"],"a":"filosofi","r":"Ordet kommer fra græsk, men på dansk skrives begge f-lyde med f, og der er ét l."},
{"l":8100,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Kommunens nye strategi: Vi sætter borgeren i centrum, tænker på tværs og skaber værdi i fællesskab.' Hvad er problemet med teksten for en kritisk læser?","o":["Det lyder teknisk, så kun eksperter kan forstå det","Det lyder flot, men siger ikke, hvad kommunen vil gøre","Det er fyldt med præcise mål og tal","Det er kun skrevet til kommunens ansatte"],"a":"Det lyder flot, men siger ikke, hvad kommunen vil gøre","r":"Ingen er uenige, og intet kan måles. Vendinger uden indhold kaldes ofte floskler."},
{"l":8118,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Hvis du kommer og hjælper bliver vi hurtigt færdige.'?","o":["kommer","bliver","hjælper","hurtigt"],"a":"hjælper","r":"Ledsætningen rummer to handlinger, der deler grundled. Den slutter først efter 'hjælper'."},
{"l":8140,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig, når et navn på to ord sættes sammen med 'tur'?","o":["New-York tur","New York tur","NewYork-tur","New York-tur"],"a":"New York-tur","r":"Navnet beholder sit mellemrum, og bindestregen binder det sammen med det sidste led."},
{"l":8163,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket fremmedord passer? 'Det var Noah, der tog ___ til indsamlingen.'","o":["initiativ","inisiativ","initiatif","initativ"],"a":"initiativ","r":"Ordet skrives med t to steder: i-ni-ti-a-tiv. Det ender på -iv."},
{"l":8184,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Mange af dem der meldte sig var fra 8. klasse.'?","o":["meldte","sig","var","klasse"],"a":"sig","r":"Den indskudte ledsætning 'der meldte sig' slutter efter 'sig'."},
{"l":8205,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'En linje, der altid har samme afstand til en anden, er ___ med den.'","o":["paralel","parralel","parallel","parrallel"],"a":"parallel","r":"Ordet kommer fra græsk: ét r, dobbelt-l i midten og ét l til sidst."},
{"l":8228,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hestene i den gamle stald levede under 'kummerlige' forhold. Hvordan havde de det?","o":["godt og overdådigt","trygt og roligt","muntert og livligt","elendigt og trist"],"a":"elendigt og trist","r":"Kummer er et gammelt ord for sorg. Kummerlige forhold er så dårlige, at det er synd for dem, der lever under dem."},
{"l":8247,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Hvis du snyder til prøven, kan det få en alvorlig ___.'","o":["konsekvens","konsekvents","konsikvens","konsekvenz"],"a":"konsekvens","r":"Navneordet ender på -ens uden t, og det skrives med kv."},
{"l":8268,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket uddrag ligner mest talesprog?","o":["Det vurderes, at planen ikke kan gennemføres.","Altså, øh, jeg tror ligesom ikke, det går.","Forslaget må desværre afvises i sin helhed.","Vi må meddele, at planen ikke kan gå igennem."],"a":"Altså, øh, jeg tror ligesom ikke, det går.","r":"Fyldord som 'altså', 'øh' og 'ligesom' er typiske for spontan tale. De andre uddrag er formelt skriftsprog."},
{"l":8290,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ledsætning hører til ledsætningen 'som Sara mødte' i: 'Den dreng, som Sara mødte, da hun boede i Vejle, hedder Anton.'?","o":["Den dreng hedder Anton","hun boede i Vejle","da hun boede i Vejle","Sara mødte Anton"],"a":"da hun boede i Vejle","r":"'Da hun boede i Vejle' fortæller, hvornår hun mødte ham. Den er altså en ledsætning til en anden ledsætning."},
{"l":8312,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord styrer at-sætningen i: 'Jeg er glad for, at du kom.'?","o":["glad","Jeg","er","for"],"a":"for","r":"Prøv med et navneord: I 'glad for gaven' hører 'gaven' sammen med forholdsordet 'for'. Det gør at-sætningen også, for et forholdsord kan styre en hel at-sætning."},
{"l":8333,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Anmelderen kalder pianistens spil 'sublimt'. Hvad mener anmelderen?","o":["at det er helt enestående godt","at det er dæmpet og næsten uhørligt","at det er teknisk fejlfrit, men koldt","at det er svagt og uden personlighed"],"a":"at det er helt enestående godt","r":"Sublim betyder ophøjet og overvældende god. Det er et stærkt rosende ord, som især bruges om kunst."},
{"l":8356,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvorfor kan 'der' ikke udelades i: 'Manden, der ringede, var venlig.'?","o":["Det er genstandsled i hovedsætningen.","Det er grundled i relativsætningen.","Det er et formelt grundled i sætningen.","Det er et biord, der angiver et sted."],"a":"Det er grundled i relativsætningen.","r":"Spørg: Hvem ringede? Det er 'der', som står for manden. Uden det ville ledsætningen mangle sit grundled."},
{"l":8378,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun bliver sendt fra kontor til kontor uden at få at vide hvorfor. Avisen kalder det 'kafkask'. Hvad menes der?","o":["at situationen er sjov og let at grine ad bagefter","at situationen er normal og hurtigt bliver løst","at situationen er absurd og umulig at gennemskue","at situationen er spændende og ender lykkeligt"],"a":"at situationen er absurd og umulig at gennemskue","r":"Ordet kommer af forfatteren Franz Kafka, hvis personer fanges i meningsløse systemer, de ikke kan forstå. Det bruges især om uigennemskuelige myndigheder."},
{"l":8400,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Elever skal have indflydelse, står der i skolens værdier. Derfor er vi blevet spurgt, om væggen skal være blå eller lyseblå.' Hvad vil skribenten sige?","o":["Eleverne har svært ved at vælge mellem to farver","Skolens værdier burde blive malet på væggen","Lyseblå er den bedste farve til skolens vægge","Eleverne må kun bestemme noget ligegyldigt"],"a":"Eleverne må kun bestemme noget ligegyldigt","r":"Blå eller lyseblå er næsten det samme, så det er ikke rigtig nogen indflydelse. Det passer dårligt med de store ord i skolens værdier."},
{"l":8422,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvem klipper håret i: 'Mads lod sit hår klippe hos frisøren.'?","o":["frisøren","Mads","Mads' far","en ven af Mads"],"a":"frisøren","r":"'Lade' betyder her, at man får en anden til at gøre noget. Mads er grundled, men det er frisøren, der klipper."},
{"l":8444,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad sker der ved point of no return i berettermodellen?","o":["Hovedpersonen bliver præsenteret for første gang","Hovedpersonen tager et valg, der ikke kan gøres om","Historien slutter, og alle tråde samles fredeligt","Publikum får at vide, hvor og hvornår historien foregår"],"a":"Hovedpersonen tager et valg, der ikke kan gøres om","r":"Efter dette punkt kan hovedpersonen ikke vende om. Det driver konflikten frem mod klimaks."},
{"l":8460,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Mødet var kun 'pro forma'. Hvad betyder det?","o":["det blev holdt for sent","det blev holdt i al hemmelighed","det blev holdt for syns skyld","det blev holdt for de professionelle"],"a":"det blev holdt for syns skyld","r":"'Pro forma' er latin for 'for formens skyld'. Man gør det, fordi det skal gøres, selv om beslutningen allerede er truffet."},
{"l":8485,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Vores ___ rektor holdt en tale ved jubilæet.'","o":["forhenværene","forhen værende","førhenværende","forhenværende"],"a":"forhenværende","r":"Ordet skrives i ét og betyder 'tidligere'. Det ender på -ende med d."},
{"l":8505,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I en roman fra 1800-tallet står der: 'Hun søgte at dølge sin skuffelse.' Hvad betyder 'dølge'?","o":["skjule","trøste","fortælle","glemme"],"a":"skjule","r":"'Dølge' er et gammelt ord for at skjule. Det bøjes 'dølger, dulgte, dulgt', så en dulgt hentydning er en skjult hentydning."},
{"l":8527,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Lægen talte med patientens ___ efter operationen.'","o":["pårørene","pårørende","pårøreende","pårørenden"],"a":"pårørende","r":"Ordet er dannet af 'på' og 'rørende' og slutter på -ende med d."},
{"l":8548,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Det var ikke den slags hus, man vendte tilbage til. Alligevel stod hun der, med det samme hul i hækken og den samme nøgle, som hun havde svoret at kaste i havet.' Hvad fortæller uddraget om hende?","o":["At hun har købt huset tilbage af de nye ejere","At hun har været på havet for at fiske den tabte nøgle op","At hun er mere bundet til stedet, end hun vil være ved","At hun aldrig har boet i huset før den dag"],"a":"At hun er mere bundet til stedet, end hun vil være ved","r":"Hun har gemt nøglen trods sit løfte. Handlingen modsiger det, hun har sagt til sig selv."},
{"l":8574,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad vil det sige, at et modernistisk digt er fragmenteret?","o":["Det er skrevet på et fremmed sprog fra fortiden","Det har altid fjorten linjer med faste enderim","Det handler om sammenhængen i en landsbys historie","Det består af brudstykker uden en samlet handling"],"a":"Det består af brudstykker uden en samlet handling","r":"Mange modernister viser en splittet verden ved at bryde teksten op i brudstykker. Læseren må selv skabe sammenhængen."},
{"l":8597,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Sætningen 'Søen er dyb' kan nominaliseres. Hvilket ord passer i: 'Søens ___ overraskede dykkerne.'","o":["dybde","dybere","dybeste","dybt"],"a":"dybde","r":"Nominalisering gør her et tillægsord til et navneord: 'dyb' bliver til 'dybde'. De andre svar er stadig former af tillægsordet."},
{"l":8620,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør en 'opportunist'?","o":["holder urokkeligt fast i sine principper","følger sin egen fordel frem for principper","ser det lyse i enhver situation","arbejder frivilligt for andres skyld"],"a":"følger sin egen fordel frem for principper","r":"Latin 'opportunus' betyder belejlig. Opportunisten griber enhver chance for at vinde noget, også selvom det strider mod det, vedkommende ellers har sagt."},
{"l":8642,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad sker der ved 'deflation' i et lands økonomi?","o":["Priserne stiger generelt","Staten låner penge i udlandet","Priserne falder generelt","Bankerne sætter renten op"],"a":"Priserne falder generelt","r":"Deflation er det modsatte af inflation. Pengene bliver mere værd, men forbrugerne udskyder ofte deres køb, og det kan skade økonomien."},
{"l":8665,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Efter snyd med regnskabet blev firmaet en 'paria' i branchen. Hvad er det blevet?","o":["en, som alle gerne vil arbejde sammen med","en, som bestemmer over alle de andre","en, som kun er med i kort tid","en, som ingen vil have noget med at gøre"],"a":"en, som ingen vil have noget med at gøre","r":"Ordet stammer fra Indien, hvor det blev brugt om folk nederst i samfundet. I dag bruges det om en, som ingen vil have noget med at gøre."},
{"l":8685,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord står på sætningsadverbialets plads i: 'Lærke har måske glemt sin nøgle.'","o":["måske","har","glemt","nøgle"],"a":"måske","r":"Et sætningsadverbial siger noget om hele sætningen. 'Måske' viser, at man ikke er sikker på, om nøglen er glemt, og det står lige efter det bøjede udsagnsord 'har'."},
{"l":8707,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Skolen bør have en lektiecafé. Mange elever får ikke hjælp derhjemme. Lektier er en del af undervisningen. Alle børn har ret til samme hjælp.' Hvilken sætning er tekstens påstand?","o":["Mange elever får ikke hjælp derhjemme.","Skolen bør have en lektiecafé.","Lektier er en del af undervisningen.","Alle børn har ret til samme hjælp."],"a":"Skolen bør have en lektiecafé.","r":"Påstanden er det, skribenten vil overbevise om. De tre andre sætninger er grundene, der skal støtte den."},
{"l":8729,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket navneord hører til udsagnsordet i 'Byen vokser hurtigt', så man kan skrive: 'Byens hurtige ___ giver mangel på boliger.'","o":["voksen","vokser","vækst","vokse"],"a":"vækst","r":"Navneordet til 'vokse' er 'vækst'. Her skifter vokalen, så nominaliseringen ligner ikke helt udsagnsordet."},
{"l":8750,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kaldes det, der antydes i en tekst uden at blive sagt direkte?","o":["overskrift","omkvæd","resumé","undertekst"],"a":"undertekst","r":"Underteksten er det, der ligger mellem linjerne. Det er især vigtigt i minimalistiske tekster og i replikker."},
{"l":8772,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kaldes teknikken, hvor tanker gengives som en uafbrudt strøm, som James Joyce er kendt for?","o":["bevidsthedsstrøm","nyhedstrekant","rammefortælling","kronologi"],"a":"bevidsthedsstrøm","r":"Bevidsthedsstrømmen gengiver tanker og indtryk, præcis som de flyder igennem hovedet, ofte uden tegnsætning."},
{"l":8790,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Et gammelt princip siger, at alle er lige for loven. Men ikke alle er lige høje. Altså passer det ikke.' Hvad er fejlen i tankegangen?","o":["Princippet nævner ikke, hvor høje folk må være i Danmark","Ordet 'lige' bruges i to forskellige betydninger","Der mangler et argument om lovens alder","Sætningerne står i den forkerte rækkefølge"],"a":"Ordet 'lige' bruges i to forskellige betydninger","r":"'Lige for loven' betyder samme rettigheder, 'lige høje' betyder samme mål. Slutningen skifter betydning undervejs."},
{"l":8814,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Det er skærmen på den bærbare pc. Hvilken form er rigtig: 'Jeg tørrede ___ af.'?","o":["pcens' skærm","pc's'ens skærm","pc'ens skærm","pc:ens skærm"],"a":"pc'ens skærm","r":"Apostroffen står én gang, mellem forkortelsen og endelsen, og genitiv-s kommer til sidst."},
{"l":8835,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find det rigtige ord: 'Hvis nogen har fundet en nøgle, bedes ___ aflevere den på kontoret.'","o":["vedkomende","vedkommene","vekommende","vedkommende"],"a":"vedkommende","r":"Ordet består af 'ved' og 'kommende' og har dobbelt-m og -ende med d."},
{"l":8852,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder forleddet 'kvasi-' i ordet 'kvasividenskabelig'?","o":["tilsyneladende, men ikke ægte","særlig grundig og velskrevet","skrevet af flere fagfolk i fællesskab","ældre end den nyeste forskning"],"a":"tilsyneladende, men ikke ægte","r":"Latin 'quasi' betyder 'som om'. Noget kvasividenskabeligt ligner videnskab, men holder ikke."},
{"l":8874,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'En ordbog registrerer sproget, som det bruges; den bestemmer det ikke. Når et nyt ord optages, er det ikke, fordi redaktørerne kan lide det, men fordi mange bruger det.' Hvad har en læser misforstået, hvis hun skriver: Ordbogen burde ikke godkende det grimme ord?","o":["At redaktørerne bruger ordet i deres eget sprog hver dag","At ordbogen ikke godkender ord, men bare skriver dem op","At ordet slet ikke findes i den ordbog, hun har læst i","At ordbøger kun indeholder ord, som mange kan lide"],"a":"At ordbogen ikke godkender ord, men bare skriver dem op","r":"Læseren tror, at ordbogen bestemmer, hvilke ord der er gode. Men der står, at den bare skriver de ord op, som folk bruger."},
{"l":8894,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led er 'Laura' i: 'Farfar gav Laura en gammel kikkert.'","o":["genstandsled","grundled","hensynsled","omsagnsled"],"a":"hensynsled","r":"Hensynsleddet er den, der modtager noget. 'En gammel kikkert' er genstandsleddet, for det er den, der bliver givet."},
{"l":8915,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Line foreslår færre lektier. Hun vil altså have, at eleverne slet ikke skal lære noget.' Hvilken argumentationsfejl er det?","o":["cirkelslutning","personangreb","falsk dilemma","stråmand"],"a":"stråmand","r":"Lines forslag bliver forvansket til noget yderliggående, som er nemt at angribe. Det kaldes et stråmandsargument."},
{"l":8935,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Alle pattedyr har lunger. Hvalen er et pattedyr. Altså har hvalen lunger.' Hvad kaldes denne måde at ræsonnere på?","o":["deduktion","induktion","intuition","spekulation"],"a":"deduktion","r":"Ved deduktion går man fra en almen regel til et enkelt tilfælde. Passer reglen, må konklusionen også passe."},
{"l":8955,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Jernbanen var blevet ødelagt med vilje, så politiet talte om ___.'","o":["sabottage","sabotage","sabotasje","sabotace"],"a":"sabotage","r":"Ordet kommer fra fransk, har ét t og ender på -age."},
{"l":8971,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning gengiver replikken 'Jeg er træt' som indirekte tale, når det er Lise, der siger den?","o":["Lise sagde, at jeg var træt.","Lise sagde, at de var trætte.","Lise sagde, at hun var træt.","Lise spurgte, om hun var træt."],"a":"Lise sagde, at hun var træt.","r":"I indirekte tale bliver 'jeg' til 'hun', og nutid rykker til datid, når 'sagde' står i datid. Replikken bliver til en at-sætning."},
{"l":8995,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Ordleddet 'pan-' i 'pandemi' kommer af græsk. Hvad fortæller det om sygdommen?","o":["Den smitter kun gennem luften","Den rammer kun børn og unge","Den forsvinder efter få uger","Den rammer alle egne af verden"],"a":"Den rammer alle egne af verden","r":"Pan- betyder alt eller alle. En epidemi er begrænset til et område, mens en pandemi breder sig globalt."},
{"l":9015,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Det er et vigtigt ___ at behandle alle ens.'","o":["princip","prinsip","princib","prinssip"],"a":"princip","r":"S-lyden skrives her med c, og ordet ender på p."},
{"l":9037,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har rigtig kongruens mellem genstandsled og tillægsord?","o":["Anton malede skuret grøn.","Anton malede skuret grønt.","Anton malede skuret grønne.","Anton malede skuret grønnes."],"a":"Anton malede skuret grønt.","r":"'Grønt' siger noget om genstandsleddet 'skuret', som står i intetkøn ental. Derfor skal tillægsordet have -t."},
{"l":9058,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Hele stadion rejste sig og jublede.' Hvilken billedfigur er der i 'stadion'?","o":["oxymoron","eufemisme","metonymi","synæstesi"],"a":"metonymi","r":"Stadion står for de mennesker, der er på stadion. Når et ord erstattes af noget nært forbundet, kaldes det metonymi."},
{"l":9076,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Nogle læger mener, at man bør fortælle patienter alt. Andre mener, at sandheden skal doseres ligesom medicin. Diskussionen er ikke løst, for begge sider ønsker at hjælpe.' Hvad er lægerne uenige om?","o":["Om de vil hjælpe, ikke hvordan de bedst gør det","Om patienterne overhovedet vil høre sandheden","Hvor god lægernes uddannelse er","Hvordan de bedst hjælper, ikke om de vil hjælpe"],"a":"Hvordan de bedst hjælper, ikke om de vil hjælpe","r":"'Begge sider ønsker at hjælpe' viser, at de er enige om det. De er uenige om, hvor meget patienten skal have at vide."},
{"l":9097,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord begynder med samme lyd som 'sjov'?","o":["chef","skov","kjole","tjener"],"a":"chef","r":"'Ch' i 'chef' udtales som sj-lyden [ɕ]. Stavemåden er anderledes, fordi ordet er lånt fra fransk."},
{"l":9115,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det at 'gå over Rubicon'?","o":["at krydse en grænse i al hemmelighed","at tage et skridt, man ikke kan fortryde","at bryde et løfte over for en god ven","at flygte fra en sag, man selv har startet"],"a":"at tage et skridt, man ikke kan fortryde","r":"Da Cæsar krydsede floden Rubicon med sin hær, var der ingen vej tilbage. Floden er blevet et billede på det afgørende skridt."},
{"l":9136,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Mange ord med 'be-' og '-hed', f.eks. 'betale' og 'frihed', kom ind i dansk i middelalderen. Fra hvilket sprog?","o":["fransk","engelsk","plattysk","latin"],"a":"plattysk","r":"Hansestædernes købmænd talte plattysk, og deres sprog satte dybe spor i dansk. Både ord og afledningsdele som 'be-' og '-hed' kom den vej."},
{"l":9158,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket stedord skal stå i: 'Selma og ___ bror kom for sent til toget.'","o":["sin","sit","sine","hendes"],"a":"hendes","r":"'Selma og … bror' er tilsammen grundled, og 'sin' kan ikke stå inde i grundleddet. Derfor hedder det 'Selma og hendes bror'."},
{"l":9179,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvorfor læses 'Den grimme ælling' ofte biografisk?","o":["Fordi Andersen selv gik fra fattigdom til berømmelse","Fordi Andersen selv voksede op på landet blandt dyr","Fordi Andersen selv var født i en fin og kendt familie","Fordi Andersen selv drømte om at rejse til varme lande"],"a":"Fordi Andersen selv gik fra fattigdom til berømmelse","r":"Ællingen ender som en smuk svane. Mange ser det som et billede på Andersens egen vej fra Odense til verdensry."},
{"l":9197,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Ytringen 'Tak for mad' mangler et udsagnsled, som man selv kan tænke til. Hvad kaldes sådan en udeladelse?","o":["parabel","ellipse","hyperbel","parentes"],"a":"ellipse","r":"En ellipse er en ytring, hvor noget er udeladt, men underforstået. Parabel og hyperbel er andre fagord, som også findes i matematikken."},
{"l":9219,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Han vendte sig ved lågen. Hun stod stadig i vinduet. Han løftede hånden. Hun trak gardinet for, men langsomt, så han nåede at se det.' Hvad er det, ordet 'langsomt' tilføjer?","o":["At hun er for svag til at trække gardinet hurtigt for","At gardinet er tungt og hænger fast i sine ringe","At hun gør det med vilje, for at han skal forstå det","At hun ikke opdagede, at han stod ude ved lågen"],"a":"At hun gør det med vilje, for at han skal forstå det","r":"'Så han nåede at se det' viser hensigten: Gardinet er et svar, en tavs meddelelse til ham."},
{"l":9235,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Organisationen sendte ___ hjælp med telte og mad til området efter jordskælvet.'","o":["humanistisk","humoristisk","hypotetisk","humanitær"],"a":"humanitær","r":"Humanitær hjælp lindrer menneskelig nød. Humanistisk bruges om fag som sprog og historie, så de to må ikke blandes sammen."},
{"l":9256,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'I kalmarunionen var Danmark, Norge og Sverige forenet.'?","o":["kalmarunionen","forenet","var","og"],"a":"kalmarunionen","r":"Kalmarunionen er navnet på en bestemt historisk union og er et egennavn."},
{"l":9279,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket stedord er rigtigt i skriftsprog: '___ danskere elsker at tale om vejret.'","o":["Os","Vi","Dem","Jer"],"a":"Vi","r":"Stedordet er grundled sammen med 'danskere', så det skal stå i grundledsform. 'Os', 'dem' og 'jer' er genstandsformer."},
{"l":9300,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad drømmer Per Sidenius om at blive i Henrik Pontoppidans 'Lykke-Per'?","o":["En berømt præst med sin egen kirke ligesom sin far","En kendt forfatter i København","En stor ingeniør med planer for hele Danmark","En rig købmand i Amerika"],"a":"En stor ingeniør med planer for hele Danmark","r":"Per Sidenius vil være ingeniør og har store planer om havne og kanaler i Danmark."},
{"l":9322,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken dansk forfatter oversatte Charles Darwins værker til dansk?","o":["Georg Brandes","Holger Drachmann","Herman Bang","J.P. Jacobsen"],"a":"J.P. Jacobsen","r":"J.P. Jacobsen var uddannet botaniker og oversatte blandt andet 'Arternes Oprindelse'."},
{"l":9340,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"René Descartes mente, at sikker viden først og fremmest kommer fra fornuften. Hvilken retning hører han til?","o":["rationalisme","romantik","impressionisme","naturalisme"],"a":"rationalisme","r":"Latin 'ratio' betyder fornuft. Rationalisterne stoler mere på tænkning end på sanserne."},
{"l":9360,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Kaffen er pakket i ___, så der næsten ikke er luft i posen.'","o":["vakum","vakuum","vacuum","vakkuum"],"a":"vakuum","r":"På dansk skrives ordet med k og dobbelt-u."},
{"l":9385,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En digter skriver 'ørkenens skib' i stedet for 'kamel'. Hvad kaldes en sådan omskrivning?","o":["palindrom","paradoks","perifrase","parodi"],"a":"perifrase","r":"Peri- betyder omkring. I en perifrase taler man uden om ordet og beskriver det med flere ord."},
{"l":9400,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket fagudtryk dækker ordene 'regninger' og 'Anna', der staves ens forfra og bagfra?","o":["anagram","akronym","homonym","palindrom"],"a":"palindrom","r":"Palindrom betyder 'der løber tilbage' på græsk. Et anagram er noget andet, for dér byttes bogstaverne om til et nyt ord."},
{"l":9430,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Til sidst blev grådigheden hans nemesis.' Hvad betyder ordet 'nemesis' her?","o":["en straf, som han selv var skyld i","en lykke, som kom helt ufortjent til ham","en hemmelig plan for at blive endnu rigere","en drøm, som han aldrig fik opfyldt"],"a":"en straf, som han selv var skyld i","r":"Nemesis var hævnens gudinde i den græske mytologi. Ordet bruges om den straf, der til sidst indhenter en."},
{"l":9445,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Det er lovligt, svarede virksomheden. Men spørgsmålet var ikke, om det var lovligt. Spørgsmålet var, om det var rimeligt.' Hvilken forskel fremhæver skribenten?","o":["Forskellen på det, virksomheden siger, og det, staten mener","Forskellen på det, man må, og det, der er i orden","Forskellen på gamle love og nye love","Forskellen på det, der er dyrt, og det, der er billigt"],"a":"Forskellen på det, man må, og det, der er i orden","r":"Virksomheden svarer på et spørgsmål, som ingen stillede. Noget kan godt være lovligt og alligevel ikke være rimeligt."},
{"l":9466,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad står i forfeltet i: 'Men i morgen tager vi til Skagen.'","o":["Men","Men i morgen","i morgen","vi"],"a":"i morgen","r":"'Men' er et bindeord, der kobler sætningen til det foregående, og det står uden for selve forfeltet. Sætningens første led er 'i morgen'."},
{"l":9488,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Flertal kan dannes med -e, -er eller uden endelse: 'huse', 'biler', 'mus'. Hvad kaldes sådanne varianter af samme morfem?","o":["homofoner","synonymer","fonemer","allomorfer"],"a":"allomorfer","r":"Allomorfer er forskellige former af det samme morfem. Her har de samme funktion, nemlig at vise flertal."},
{"l":9509,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kaldes det, når publikum ved noget, som personerne på scenen ikke ved?","o":["dramatisk ironi","metafiktion","synæstesi","kairos"],"a":"dramatisk ironi","r":"Publikum ser mere end personerne, og det skaber spænding eller komik."},
{"l":9528,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Da bageriet lukkede, kom lugten af brød ikke længere ind ad vinduerne i Stræde 4. Det var først da, folk sagde, at de havde kunnet lide den. I alle de år havde de klaget.' Hvad er pointen?","o":["Man har aldrig kunnet lide bagerier, der ligger tæt på","Man sætter ofte først pris på noget, når det er væk","Folk klager altid mere, jo tættere de bor på hinanden","Folk i Stræde 4 har glemt, at bageriet er lukket"],"a":"Man sætter ofte først pris på noget, når det er væk","r":"I mange år klagede folk over lugten. Først da den var væk, sagde de, at de kunne lide den."},
{"l":9550,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad tilstræber et land, der ønsker 'autarki'?","o":["at handle mest muligt med udlandet","at afskaffe sin egen valuta","at klare sig økonomisk uden import","at sælge sin energi til nabolandene"],"a":"at klare sig økonomisk uden import","r":"Græsk 'autarkeia' betyder selvtilstrækkelighed. Et land med autarki er økonomisk selvforsynende."},
{"l":9570,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find ordet: 'Det kræver stor ___ at træne hver morgen.'","o":["diciplin","disiplin","dissiplin","disciplin"],"a":"disciplin","r":"Ordet indeholder sc: dis-ci-plin. Det er nemt at glemme s'et."},
{"l":9588,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Spørgsmålet: Hvad vil du være, når du bliver stor? forudsætter, at man ikke er noget endnu.' Hvad kritiserer skribenten?","o":["At man taler, som om barnet ikke er nogen endnu","At voksne ikke spørger børn nok om deres fremtid","At børn i dag vælger forkerte uddannelser","At spørgsmålet er for svært for de mindste"],"a":"At man taler, som om barnet ikke er nogen endnu","r":"Når man spørger, hvad barnet vil være, lyder det, som om det ikke allerede er nogen. Det er det, skribenten ikke bryder sig om."},
{"l":9610,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"To firmaer indgik et 'quid pro quo'. Hvad er det?","o":["en gave uden forventning om noget","en ydelse mod en modydelse","en straf for en gammel fejl","en aftale, der er ugyldig fra starten"],"a":"en ydelse mod en modydelse","r":"Latin 'quid pro quo' betyder 'noget for noget'. Hver part får altså noget til gengæld for det, den giver."},
{"l":9631,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad kan man vide om bilen i: 'Jonas vaskede hans bil.'","o":["Bilen tilhører Jonas selv.","Bilen tilhører flere personer.","Bilen tilhører en anden end Jonas.","Bilen er ny og meget dyr."],"a":"Bilen tilhører en anden end Jonas.","r":"'Hans' kan ikke pege tilbage på grundleddet. Hvis Jonas vaskede sin egen bil, ville der stå 'sin'."},
{"l":9652,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad sætter nykritikken i centrum, når en tekst skal læses?","o":["Forfatterens opvækst og familie","Den samtidige læsers reaktioner","Tidens samfund og historie","Tekstens egne ord og opbygning"],"a":"Tekstens egne ord og opbygning","r":"Nykritikken læser teksten tæt og lader forfatterens liv ligge. Svaret skal findes i selve teksten."},
{"l":9674,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad betyder det, at en tekst er flertydig?","o":["Den kan forstås på flere måder, der kan begrundes","Den er skrevet af flere forfattere på én gang","Den er oversat til flere sprog end dansk og engelsk","Den er så utydelig, at den ikke kan forstås af nogen"],"a":"Den kan forstås på flere måder, der kan begrundes","r":"Flertydighed er en styrke i litteraturen. Flere tolkninger kan være rimelige, når de støtter sig til teksten."},
{"l":9695,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Vi måler det, der kan måles, og snart er det, der måles, også det, der tæller. Læsehastighed står i tabellen. Læselyst står ingen steder.' Hvad advarer skribenten imod?","o":["At lærerne måler læsehastigheden på en forkert måde","At vi glemmer det, der ikke kan måles","At eleverne læser for hurtigt til at forstå teksten","At tabeller er sværere at forstå end almindelig tekst"],"a":"At vi glemmer det, der ikke kan måles","r":"Fordi læsehastighed kan tælles, bliver den vigtig, selv om læselyst måske betyder mere. Målene styrer, hvad vi ser."},
{"l":9718,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs novellens første linje: 'Den morgen, vores hund begyndte at tale, var det mandag.' Hvad gør den første linje ved læseren?","o":["Den gør én tryg, for mandag er en almindelig dag","Den forklarer, hvorfor hunden kan tale","Den gør én nysgerrig, for hunde kan jo ikke tale","Den fortæller, hvordan novellen slutter"],"a":"Den gør én nysgerrig, for hunde kan jo ikke tale","r":"Noget umuligt og en helt almindelig mandag står side om side. Det fanger læseren med det samme, og det er anslagets opgave."},
{"l":9735,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Der er ingen adgang for ___ på byggepladsen.'","o":["uvedkomende","uvedkommene","uvekommende","uvedkommende"],"a":"uvedkommende","r":"Ordet består af 'u' og 'vedkommende' og har dobbelt-m og -ende med d."},
{"l":9752,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner en 'forstokket' holdning?","o":["Den er stivnet og lukket for nye tanker","Den er åben og nysgerrig over for alt nyt","Den er skjult bag en stor og venlig facade","Den er nyopstået og endnu ikke gennemtænkt"],"a":"Den er stivnet og lukket for nye tanker","r":"Ordet er beslægtet med 'stok' og antyder noget stift. Den forstokkede lader sig ikke overbevise af argumenter."},
{"l":9776,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma, når ledsætningen gentages af 'det': 'At han er sur det kan jeg godt forstå.'?","o":["han","sur","kan","forstå"],"a":"sur","r":"Ledsætningen står først og gentages af 'det'. Den skal altid afsluttes med komma."},
{"l":9796,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken omskrivning bruger en nominalisering af: 'Fordi det regnede kraftigt, blev kampen aflyst.'","o":["Det regnede kraftigt, så kampen blev aflyst.","Kampen blev aflyst, da det regnede kraftigt.","På grund af kraftigt regnvejr blev kampen aflyst.","Da det regnede kraftigt, aflyste de kampen."],"a":"På grund af kraftigt regnvejr blev kampen aflyst.","r":"'Fordi det regnede kraftigt' er en hel sætning med et udsagnsord. I 'På grund af kraftigt regnvejr' er det samme sagt med navneordet 'regnvejr', og det er en nominalisering."},
{"l":9817,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken forfatter skrev 'Løgneren' fra 1950, der foregår på en lille ø?","o":["Hans Kirk","Tom Kristensen","Klaus Rifbjerg","Martin A. Hansen"],"a":"Martin A. Hansen","r":"Martin A. Hansen var en central forfatter efter krigen. I 'Løgneren' fortæller skolelæreren Johannes Vig."},
{"l":9839,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken historisk roman af Johannes V. Jensen, udgivet 1900–01, foregår på Christian 2.s tid?","o":["Kongens Fald","Fru Marie Grubbe","Lykke-Per","Himmerlandsfolk"],"a":"Kongens Fald","r":"'Kongens Fald' følger både kong Christian 2. og landsknægten Mikkel Thøgersen."},
{"l":9857,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes en logisk slutning med to præmisser og en konklusion?","o":["aforisme","syllogisme","neologisme","solecisme"],"a":"syllogisme","r":"Syllogismen stammer fra Aristoteles' logik. Et eksempel: Alle pattedyr har lunger. Hvalen er et pattedyr. Altså har hvalen lunger."},
{"l":9883,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilket værk af islænderen Snorre Sturlason er en hovedkilde til nordisk mytologi?","o":["Gesta Danorum","Beowulf","Edda","Iliaden"],"a":"Edda","r":"Snorres Edda fortæller om de nordiske guder. 'Gesta Danorum' er Saxos Danmarkshistorie."},
{"l":9902,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"'Det var ikke helt dumt', siger Noor om et glimrende forslag. Hvilken sproglig figur bruger hun?","o":["hyperbel","alliteration","allegori","litote"],"a":"litote","r":"En litote er en underdrivelse, hvor man nægter det modsatte. Ordene siger mindre, end der menes."},
{"l":9921,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'På sociale medier opfordres vi til at være ægte. Men i samme øjeblik man overvejer, hvordan ens ægthed virker på andre, er den blevet en rolle. Den, der græder foran kameraet, har først indstillet lyset.' Hvad er tekstens paradoks?","o":["Man er ikke ægte længere, når man tænker på, hvordan det ser ud","Sociale medier gør folk mere ærlige, end de ønsker at være","Lys er vigtigere end følelser, når man filmer sig selv","At græde foran andre er sværere end at græde alene"],"a":"Man er ikke ægte længere, når man tænker på, hvordan det ser ud","r":"Man skal være ægte, men så snart man tænker på, hvordan det virker på andre, spiller man en rolle. Den, der stiller lyset, før hun græder, er et eksempel."},
{"l":9940,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Historien om digterens første møde med kongen er apokryf.' Hvad betyder det?","o":["Den er smuk og rørende","Dens ægthed er tvivlsom","Den er bevist af forskere","Den er forbudt at trykke"],"a":"Dens ægthed er tvivlsom","r":"Græsk 'apokryphos' betyder skjult. I dag bruges ordet om noget, der ikke er sikkert belagt."},
{"l":9961,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken rækkefølge viser det danske sprogs udvikling fra ældst til yngst?","o":["runedansk, urnordisk, nydansk, gammeldansk","gammeldansk, urnordisk, runedansk, nydansk","urnordisk, runedansk, gammeldansk, nydansk","urnordisk, gammeldansk, runedansk, nydansk"],"a":"urnordisk, runedansk, gammeldansk, nydansk","r":"Urnordisk er det ældste trin, og runedansk er sproget i vikingetiden. Gammeldansk er middelalderens sprog, og nydansk tager fat omkring reformationen."},
{"l":9983,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning er en sproghandling, hvor man udfører handlingen ved at sige ordene?","o":["Jeg ryddede op i går aftes.","Mor rydder tit op om aftenen.","Det er dejligt at have ryddet op.","Jeg lover at rydde op i morgen."],"a":"Jeg lover at rydde op i morgen.","r":"Når man siger 'Jeg lover', har man givet løftet. Ordene beskriver ikke en handling, de er selve handlingen."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
